 5	    public static int modPow(ModularExponentiationInput input) {
 6	        int normalizedBase = normalizeBase(input.base(), input.modulus());
 7	        int remainingExponent = input.exponent();
 8	        long result = 1 % input.modulus();
 9	
10	        while (remainingExponent > 0) {
11	            if ((remainingExponent & 1) != 0) {
12	                result = multiplyMod(result, normalizedBase, input.modulus());
13	            }
14	
15	            normalizedBase = multiplyMod(normalizedBase, normalizedBase, input.modulus());
16	            remainingExponent >>= 1;
17	        }
18	
19	        return (int) result;
20	    }
21	
22	    public static int modPow(int base, int exponent, int modulus) {
23	        return modPow(new ModularExponentiationInput(base, exponent, modulus));
24	    }
